import{az as a,P as i,Q as t,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/vue/index.md","filePath":"面试题/vue/index.md","lastUpdated":1743419999000}'),l={name:"面试题/vue/index.md"};function n(u,e,s,o,p,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="vue-组件通信" tabindex="-1">Vue 组件通信 <a class="header-anchor" href="#vue-组件通信" aria-label="Permalink to “Vue 组件通信”">​</a></h2><ul><li>props、$emit</li><li>$on、$emit</li><li>vuex</li><li>$attrs、$listeners</li><li>$parent 、 $children 、 ref</li><li>provide、inject</li></ul><h2 id="computed-和-watch-的区别" tabindex="-1">computed 和 watch 的区别 <a class="header-anchor" href="#computed-和-watch-的区别" aria-label="Permalink to “computed 和 watch 的区别”">​</a></h2><ul><li>computed创建的属性会被缓存，在页面多次使用也只会触发一次。依赖的数据发生变化时会再次更新。</li><li>watch用于异步监听数据。</li></ul><h2 id="完整版-vue-js-和运行版-vue-runtime-js-有什么区别" tabindex="-1">完整版（vue.js）和运行版（vue.runtime.js）有什么区别 <a class="header-anchor" href="#完整版-vue-js-和运行版-vue-runtime-js-有什么区别" aria-label="Permalink to “完整版（vue.js）和运行版（vue.runtime.js）有什么区别”">​</a></h2><p>template解析器占据代码的三分之一。完整版包含template解析器；运行版去除了template解析器，保留了核心功能</p><h2 id="key起到什么作用" tabindex="-1">key起到什么作用 <a class="header-anchor" href="#key起到什么作用" aria-label="Permalink to “key起到什么作用”">​</a></h2><p>vnode 在更新时会用 key 进行对比，在对比时发现相同的 key， 直接会复用元素。如果不填写 key，vue 则会默认生成，不会干扰 vnode 的对比。更新 key 时页面元素会重新渲染。</p><h2 id="v-show和v-if的区别" tabindex="-1">v-show和v-if的区别 <a class="header-anchor" href="#v-show和v-if的区别" aria-label="Permalink to “v-show和v-if的区别”">​</a></h2><h2 id="vue最小化更新过程是什么样子的" tabindex="-1">Vue最小化更新过程是什么样子的 <a class="header-anchor" href="#vue最小化更新过程是什么样子的" aria-label="Permalink to “Vue最小化更新过程是什么样子的”">​</a></h2><h2 id="vue-如何实现指令系统" tabindex="-1">Vue 如何实现指令系统 <a class="header-anchor" href="#vue-如何实现指令系统" aria-label="Permalink to “Vue 如何实现指令系统”">​</a></h2><h2 id="用到了哪些开发小技巧" tabindex="-1">用到了哪些开发小技巧 <a class="header-anchor" href="#用到了哪些开发小技巧" aria-label="Permalink to “用到了哪些开发小技巧”">​</a></h2><ul><li>提升性能：函数科里化</li><li>函数拦截：处理数组的 push、pop、shift、unshift、revers、sort、splice 方法</li></ul><h2 id="vuex-和-pinia-的区别" tabindex="-1">vuex 和 pinia 的区别 <a class="header-anchor" href="#vuex-和-pinia-的区别" aria-label="Permalink to “vuex 和 pinia 的区别”">​</a></h2><p>Pinia和Vuex都是Vue.js的状态管理库，它们之间的区别可以从以下几个方面进行归纳：</p><p>与Vue版本的兼容性：</p><p>Vuex：主要用于Vue 2，虽然也可以用于Vue 3，但需要使用Vuex 4.x版本。 Pinia：专为Vue 3开发，充分利用了Vue 3的Composition API，不提供对Vue 2的支持。 状态管理的方式：</p><p>Vuex：遵循单一状态树的概念，将所有应用状态存储在一个全局的store中。通过actions、mutations和getters来修改和获取状态，具有严格的规则保证状态以一种可预测的方式发生变化。 Pinia：采用更加模块化的方法来管理状态，每个模块（store）都有自己的状态、操作和getters。这种方式使得代码更加分散且自包含，降低了复杂性。 异步操作的处理：</p><p>Vuex：异步操作通常需要在actions中处理，这可能导致代码相对冗长。 Pinia：支持在模块中使用async/await来更轻松地处理异步操作，使代码更加清晰。 TypeScript支持：</p><p>Vuex：在处理类型和TypeScript支持方面相对较弱，虽然可以使用TypeScript，但需要额外的工作。 Pinia：专门为TypeScript设计，具有更强大的类型支持。它充分利用了Vue 3的Composition API的类型推断，使得开发者可以更容易地编写类型安全的代码。 使用场景：</p><p>Vuex：适合大型、复杂的Vue应用，尤其是那些需要严格遵循Flux架构原则的应用。Vuex的严格性和规范性使得它成为管理复杂状态的首选。 Pinia：适合Vue 3项目，特别是那些希望采用Composition API进行开发的项目。Pinia的灵活性和模块化使得它成为Vue 3项目中状态管理的理想选择。 综上所述，Pinia和Vuex在兼容性、状态管理方式、异步操作处理、TypeScript支持以及使用场景等方面存在明显的差异。开发者在选择时应根据项目的具体需求和技术栈来做出决策。</p>',21)])])}const v=a(l,[["render",n]]);export{m as __pageData,v as default};
